#include <bits/stdc++.h>
using namespace std;
int main(){
    int m; cin >> m;
    vector<int> D(m);
    for (auto &d : D) cin >> d; // digits 1..9, given sorted ascending
    long long N; cin >> N;
    string s = to_string(N);
    int L = s.size();
    // lengths 1..L-1: all combinations valid (digits are 1-9, never leading zero issue)
    long long total = 0;
    long long p = 1; // m^0
    for (int len = 1; len < L; len++) {
        p *= m;
        total += p;
    }
    // length == L: digit DP style scan
    bool matchedFull = false;
    for (int pos = 0; pos < L; pos++) {
        int nd = s[pos]-'0';
        int cntLess = 0;
        for (int d : D) if (d < nd) cntLess++;
        long long power = 1;
        for (int i = 0; i < L-1-pos; i++) power *= m;
        total += (long long)cntLess * power;
        // check if nd itself is achievable (in D) to continue tight
        bool found = false;
        for (int d : D) if (d == nd) { found = true; break; }
        if (!found) { matchedFull = false; goto done; }
        if (pos == L-1) matchedFull = true;
    }
    done:
    if (matchedFull) total += 1;
    cout << total << endl;
}

#include <bits/stdc++.h>
using namespace std;
string s;
int V; // candidate digit sum target
long long memo[20][170][170];
bool vis[20][170][170];
long long dfs(int pos, int sumSoFar, int rem, bool tight) {
    if (sumSoFar > V) return 0;
    if (pos == (int)s.size()) return (sumSoFar == V && rem == 0) ? 1 : 0;
    if (!tight && vis[pos][sumSoFar][rem]) return memo[pos][sumSoFar][rem];
    int limit = tight ? (s[pos]-'0') : 9;
    long long res = 0;
    for (int d = 0; d <= limit; d++) {
        int nrem = (rem*10+d) % V;
        res += dfs(pos+1, sumSoFar+d, nrem, tight && d==limit);
    }
    if (!tight) { vis[pos][sumSoFar][rem] = true; memo[pos][sumSoFar][rem] = res; }
    return res;
}
long long countUpTo(long long n) {
    if (n <= 0) return 0;
    s = to_string(n);
    long long total = 0;
    int maxSum = 9 * (int)s.size();
    for (V = 1; V <= maxSum; V++) {
        memset(vis, 0, sizeof(vis));
        total += dfs(0, 0, 0, true);
    }
    return total;
}
int main(){
    long long l, r;
    cin >> l >> r;
    cout << (countUpTo(r) - countUpTo(l-1)) << endl;
}

