#include <bits/stdc++.h>
using namespace std;
int R, S, P;
map<tuple<int,int,int>, array<double,3>> memo;
// returns {prob rock survives, prob scissors survives, prob paper survives}
array<double,3> solve(int r, int s, int p) {
    // check absorbing: at most one of r,s,p is positive
    int nz = (r>0) + (s>0) + (p>0);
    if (nz <= 1) {
        array<double,3> res = {0,0,0};
        if (r>0) res[0]=1;
        else if (s>0) res[1]=1;
        else if (p>0) res[2]=1;
        return res;
    }
    auto key = make_tuple(r,s,p);
    auto it = memo.find(key);
    if (it != memo.end()) return it->second;
    long long rockScissors = (long long)r*s; // rock beats scissors -> s decreases
    long long scissorsPaper = (long long)s*p; // scissors beats paper -> p decreases
    long long paperRock = (long long)p*r; // paper beats rock -> r decreases
    long long crossTotal = rockScissors + scissorsPaper + paperRock;
    array<double,3> res = {0,0,0};
    if (rockScissors > 0) {
        auto sub = solve(r, s-1, p);
        double w = (double)rockScissors / crossTotal;
        for (int i=0;i<3;i++) res[i] += w*sub[i];
    }
    if (scissorsPaper > 0) {
        auto sub = solve(r, s, p-1);
        double w = (double)scissorsPaper / crossTotal;
        for (int i=0;i<3;i++) res[i] += w*sub[i];
    }
    if (paperRock > 0) {
        auto sub = solve(r-1, s, p);
        double w = (double)paperRock / crossTotal;
        for (int i=0;i<3;i++) res[i] += w*sub[i];
    }
    memo[key] = res;
    return res;
}
int main(){
    cin >> R >> S >> P;
    auto res = solve(R,S,P);
    cout << fixed << setprecision(6) << res[0] << " " << res[1] << " " << res[2] << endl;
}

